{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C26"],
      "claim": "Ilomastat, a polar, high-molecular-weight MMP inhibitor with a hydroxamate and peptide-like backbone, was reported to have 'not good' oral bioavailability, supporting low F for a large, ionizable, poorly permeable molecule.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C35"],
      "claim": "Labetalol, a lipophilic drug with extensive first-pass metabolism, had an oral bioavailability of only 18% in a 70 kg human, supporting F<20% for a lipophilic compound with high presystemic clearance.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C73"],
      "claim": "Propranolol, despite near-complete absorption, had absolute oral bioavailability as low as 16% due to high hepatic extraction, supporting low F for a lipophilic, high-first-pass compound.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "Rosuvastatin, the closest statin analogue with the same dihydroxyheptanoic acid side chain, has an absolute oral bioavailability of approximately 20% in healthy volunteers; this is at the threshold and slightly contradicts a low prediction, but does not exceed 20%.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is atorvastatin, a statin with known absolute oral bioavailability of approximately 14% (<20%). The closest supplied statin evidence (rosuvastatin) is only at the 20% threshold, and the query's lipophilic pyrrole/anilide structure, poor solubility, and extensive first-pass metabolism support F<20%. Therefore predict low.",
  "evidence_gaps": [
    "No direct atorvastatin bioavailability record is included in the supplied evidence; the prediction relies on known human data (F≈14%) and close statin analogy.",
    "Ilomastat's 'not good' oral bioavailability is qualitative and not explicitly tied to the 20% threshold.",
    "Labetalol and propranolol bioavailability values are variable and dose-dependent, adding uncertainty to their threshold relevance."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

